-- 57 Picture House: the film is the engine's (`video_player`); this pauses
-- and restarts it with Video.set, and lets the screen's light breathe with
-- the projector's flicker. Generated by tools/gen_scenes.py.

script = { tick_rate = 60 }

local nav = require("nav")
local SCENE = "scenes/57-picture-house.scene"
local captions = true
local playing = true
local screen, light, beam, status
local t = 0

function init(entity)
    screen = Entity.find_by_name("Screen")
    light = Entity.find_by_name("ScreenLight")
    beam = Entity.find_by_name("Beam")
    status = Entity.find_by_name("Status")
end

function update(entity, dt)
    nav.tick(SCENE)
    if Input.is_key_just_pressed("Tab") then captions = nav.toggle_ui_captions(captions) end
    if Input.is_key_just_pressed("Space") and screen then
        playing = not playing
        Video.set(screen, "playing", playing)
    end
    if Input.is_key_just_pressed("R") and screen then
        Video.set(screen, "seek", 0)
        playing = true
        Video.set(screen, "playing", true)
    end
    t = t + dt
    local flicker = playing and (0.92 + 0.08 * math.sin(t * 47) * math.sin(t * 13)) or 0.75
    if light then Lighting.set_intensity(light, 0.9 * flicker) end
    if beam then Sprite.set_color(beam, 1.08 * flicker, 1.02 * flicker, 0.9 * flicker, playing and 0.05 or 0.015) end
    if status then UI.set_text(status, playing and "now showing: The Voyage" or "intermission") end
end
